import{_ as e,o as t,c as i,a2 as s}from"./chunks/framework.Dhf_H6O0.js";const u=JSON.parse('{"title":"Install MCPBehindIT","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/install-app.md","filePath":"getting-started/install-app.md"}'),n={name:"getting-started/install-app.md"};function o(l,a,r,d,h,p){return t(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="install-mcpbehindit" tabindex="-1">Install MCPBehindIT <a class="header-anchor" href="#install-mcpbehindit" aria-label="Permalink to &quot;Install MCPBehindIT&quot;">​</a></h1><p>There are two ways to install MCPBehindIT on your Mac. The one-line installer is the fastest.</p><h2 id="option-a-one-line-installer-recommended" tabindex="-1">Option A: One-Line Installer (recommended) <a class="header-anchor" href="#option-a-one-line-installer-recommended" aria-label="Permalink to &quot;Option A: One-Line Installer (recommended)&quot;">​</a></h2><ol><li>Open <strong>Terminal</strong> (search for &quot;Terminal&quot; in Spotlight, or find it in Applications → Utilities).</li><li>Copy and paste this command, then press <strong>Return</strong>:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://halfcross.github.io/mbit-mcpo-proxy-download/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><ol start="3"><li>The installer downloads the latest version, copies it to your Applications folder, and clears macOS quarantine automatically.</li><li>When you see <strong>&quot;Done&quot;</strong>, MCPBehindIT is ready in your Applications folder.</li></ol><div class="tip custom-block"><p class="custom-block-title">What does this command do?</p><p>It downloads a small script that fetches the latest MCPBehindIT release from GitHub, mounts the disk image, copies the app to <code>/Applications</code>, and runs <code>xattr -cr</code> to prevent macOS from showing a &quot;damaged app&quot; warning. No passwords or admin rights are needed.</p></div><h2 id="option-b-manual-install-download-dmg" tabindex="-1">Option B: Manual Install (download DMG) <a class="header-anchor" href="#option-b-manual-install-download-dmg" aria-label="Permalink to &quot;Option B: Manual Install (download DMG)&quot;">​</a></h2><ol><li>Go to the <a href="https://github.com/halfcross/mbit-mcpo-proxy-download/releases" target="_blank" rel="noreferrer">Releases page</a>.</li><li>Download the latest <code>.dmg</code> file.</li><li>Double-click the DMG to open it.</li><li>Drag <strong>MCPBehindIT</strong> into your <strong>Applications</strong> folder.</li><li>Open Terminal and run:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/Applications/MCPBehindIT.app&quot;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Why the extra Terminal step?</p><p>MCPBehindIT is not distributed through the Mac App Store and uses ad-hoc code signing. macOS may show a &quot;damaged&quot; or &quot;can&#39;t be opened&quot; warning. The <code>xattr -cr</code> command removes the quarantine flag and fixes this. You only need to do this once.</p></div><h2 id="launch-the-app" tabindex="-1">Launch the app <a class="header-anchor" href="#launch-the-app" aria-label="Permalink to &quot;Launch the app&quot;">​</a></h2><p>Open <strong>MCPBehindIT</strong> from your Applications folder, Launchpad, or Spotlight. The first time you launch it, you&#39;ll see the <a href="./activate-license.html">license activation</a> screen.</p><h2 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next step&quot;">​</a></h2><p>Before we activate the license, let&#39;s make sure <a href="./docker.html">Docker Desktop</a> is ready.</p>',15)])])}const m=e(n,[["render",o]]);export{u as __pageData,m as default};
